import 'dart:convert';
import 'package:flutter/foundation.dart';
import 'package:pointycastle/export.dart';

class DecryptUtils {
  final String imgKeyB64;

  DecryptUtils(this.imgKeyB64);

  Future<Uint8List> decryptBufferAsync(Uint8List encrypted) async {
    // Web 端 compute 只是同步 fallback，但 API 统一
    return compute(_decryptIsolate, _DecryptParams(encrypted, imgKeyB64));
  }

  Future<String> decryptStringAsync(String encryptedB64) async {
    final encrypted = base64Decode(encryptedB64);
    final decrypted = await decryptBufferAsync(encrypted);
    return utf8.decode(decrypted);
  }

  Future<T> decryptJsonAsync<T>(String encryptedB64) async {
    final text = await decryptStringAsync(encryptedB64);
    return jsonDecode(text) as T;
  }
}

Uint8List decryptBufferSync(Uint8List encrypted, String imgKeyB64) {
  return _DecryptWorker.decryptBuffer(
    encrypted: encrypted,
    imgKeyB64: imgKeyB64,
  );
}

class _DecryptWorker {
  static Uint8List normalizeKey(String b64Key) {
    final raw = base64Decode(b64Key);

    if (raw.length == 16) return Uint8List.fromList(raw);
    if (raw.length > 16) return Uint8List.fromList(raw.sublist(0, 16));

    final padded = Uint8List(16);
    padded.setRange(0, raw.length, raw);
    return padded;
  }

  /// encrypted = IV(16) + Ciphertext
  static Uint8List decryptBuffer({
    required Uint8List encrypted,
    required String imgKeyB64,
  }) {
    final key = normalizeKey(imgKeyB64);
    final iv = encrypted.sublist(0, 16);
    final ciphertext = encrypted.sublist(16);

    final cipher = PaddedBlockCipherImpl(
      PKCS7Padding(),
      CBCBlockCipher(AESEngine()),
    );

    cipher.init(
      false,
      PaddedBlockCipherParameters<ParametersWithIV<KeyParameter>, Null>(
        ParametersWithIV<KeyParameter>(KeyParameter(key), iv),
        null,
      ),
    );

    return cipher.process(ciphertext);
  }
}

class _DecryptParams {
  final Uint8List encrypted;
  final String imgKeyB64;

  _DecryptParams(this.encrypted, this.imgKeyB64);
}

Uint8List _decryptIsolate(_DecryptParams params) {
  return _DecryptWorker.decryptBuffer(
    encrypted: params.encrypted,
    imgKeyB64: params.imgKeyB64,
  );
}

